// ==================== АНТЕННА (Slave) ====================
#include <Servo.h>
#include <SoftwareSerial.h>
#include <Wire.h>
#include <QMC5883LCompass.h>
#include <EEPROM.h>

// ---------- Сервоприводы ----------
Servo servoH;
Servo servoV;
const int PIN_H = 9;
const int PIN_V = 5;

// ---------- RS485 (SoftwareSerial) ----------
SoftwareSerial rs485(10, 11);       // RX = D10, TX = D11
const int RS485_DE_RE = 2;

// ---------- Компас ----------
QMC5883LCompass compass;

// ---------- Состояние ----------
int angleH = 90;
int angleV = 90;
int azimuth = 0;
int targetAzimuth = 0;
bool stabilizationMode = false;

// ---------- PID ----------
float Kp = 0.8, Ki = 0.05, Kd = 0.3;
float errPrev = 0, integral = 0;
unsigned long lastPid = 0;

// ---------- Калибровка ----------
int calMinX = 32767, calMaxX = -32768;
int calMinY = 32767, calMaxY = -32768;
int calMinZ = 32767, calMaxZ = -32768;
bool calibrating = false;
unsigned long calibStart = 0;
const unsigned long CALIB_DURATION = 20000;

// ---------- EEPROM ----------
const int EEPROM_CALIB_FLAG = 8;
const int EEPROM_CALIB_BASE = 10;
const int EEPROM_CALIB_VALUE = 0xCD;

// ---------- Тайминги ----------
unsigned long lastAzSend = 0;
const int AZ_SEND_INTERVAL = 100;
unsigned long lastReadRS = 0;
const int RS_READ_INTERVAL = 20;
unsigned long lastServo = 0;
const int SERVO_INTERVAL = 40;

// ---------- Приём RS485 ----------
String rxBuffer = "";

void setup() {
  Serial.begin(9600);
  rs485.begin(9600);
  pinMode(RS485_DE_RE, OUTPUT);
  digitalWrite(RS485_DE_RE, LOW);

  servoH.attach(PIN_H);
  servoV.attach(PIN_V);
  servoH.write(angleH);
  servoV.write(angleV);

  compass.init();
  delay(200);
  loadCalibration();

  lastPid = millis();

  Serial.println(F("=== ANTENNA READY ==="));
}

void loop() {
  unsigned long now = millis();

  if (now - lastReadRS >= RS_READ_INTERVAL) {
    lastReadRS = now;
    readRS485();
  }

  if (calibrating) {
    runCalibration();
    return;
  }

  compass.read();
  azimuth = compass.getAzimuth();
  if (azimuth < 0) azimuth += 360;

  if (now - lastServo >= SERVO_INTERVAL) {
    lastServo = now;
    if (stabilizationMode) {
      stabilizeWithPid(now);
    }
    servoH.write(angleH);
    servoV.write(angleV);
  }

  if (now - lastAzSend >= AZ_SEND_INTERVAL) {
    lastAzSend = now;
    String pkt = "A:";
    pkt += padNum(azimuth, 3);
    pkt += "\n";
    sendRS485(pkt);
  }
}

// ==================== ЧТЕНИЕ RS485 ====================
void readRS485() {
  while (rs485.available()) {
    char c = rs485.read();
    if (c == '\n') {
      parsePacket(rxBuffer);
      rxBuffer = "";
    } else {
      rxBuffer += c;
      if (rxBuffer.length() > 32) rxBuffer = "";
    }
  }
}

void parsePacket(String p) {
  p.trim();

  if (p.startsWith("H:") && p.indexOf("V:") > 0) {
    int hStart = 2;
    int vPos = p.indexOf("V:");
    angleH = constrain(p.substring(hStart, vPos).toInt(), 0, 180);
    angleV = constrain(p.substring(vPos + 2).toInt(), 0, 180);
    Serial.print(F("RX angles H="));
    Serial.print(angleH);
    Serial.print(F("V="));
    Serial.println(angleV);
  }
  else if (p.startsWith("S:")) {
    stabilizationMode = (p.substring(2).toInt() == 1);
    if (stabilizationMode) {
      integral = 0;
      errPrev = 0;
      lastPid = millis();
    }
    Serial.print(F("RX stab mode: "));
    Serial.println(stabilizationMode ? F("ON") : F("OFF"));
  }
  else if (p.startsWith("T:")) {
    targetAzimuth = p.substring(2).toInt();
    if (targetAzimuth < 0) targetAzimuth += 360;
    Serial.print(F("RX target Az: "));
    Serial.println(targetAzimuth);
  }
  else if (p.startsWith("C:")) {
    startCalibration();
    Serial.println(F("RX calibrate command"));
  }
}

// ==================== PID СТАБИЛИЗАЦИЯ ====================
void stabilizeWithPid(unsigned long now) {
  float dt = (now - lastPid) / 1000.0;
  if (dt < 0.01) dt = 0.01;
  lastPid = now;

  float err = targetAzimuth - azimuth;
  while (err > 180) err -= 360;
  while (err < -180) err += 360;

  if (abs(err) < 2.0) err = 0;

  float P = Kp * err;
  integral += err * dt;
  integral = constrain(integral, -100, 100);
  float I = Ki * integral;
  float D = Kd * (err - errPrev) / dt;
  errPrev = err;

  float out = P + I + D;
  out = constrain(out, -3.0, 3.0);

  if (abs(err) > 2.0) {
    angleH = constrain(angleH + (int)out, 0, 180);
  }
}

// ==================== ОТПРАВКА RS485 ====================
void sendRS485(String data) {
  digitalWrite(RS485_DE_RE, HIGH);
  delayMicroseconds(50);
  rs485.print(data);
  rs485.flush();
  delayMicroseconds(50);
  digitalWrite(RS485_DE_RE, LOW);
}

// ==================== КАЛИБРОВКА ====================
void startCalibration() {
  calibrating = true;
  calibStart = millis();
  calMinX = calMinY = calMinZ = 32767;
  calMaxX = calMaxY = calMaxZ = -32768;
  Serial.println(F("=== CALIBRATION STARTED ==="));
  Serial.println(F("Rotate antenna 360 deg for 20 sec"));
}

void runCalibration() {
  compass.read();
  int x = compass.getX(), y = compass.getY(), z = compass.getZ();

  if (x < calMinX) calMinX = x;
  if (x > calMaxX) calMaxX = x;
  if (y < calMinY) calMinY = y;
  if (y > calMaxY) calMaxY = y;
  if (z < calMinZ) calMinZ = z;
  if (z > calMaxZ) calMaxZ = z;

  unsigned long elapsed = millis() - calibStart;
  unsigned long remaining = (CALIB_DURATION - elapsed) / 1000;

  static unsigned long lastPrint = 0;
  if (millis() - lastPrint > 2000) {
    lastPrint = millis();
    Serial.print(F("Calibration: "));
    Serial.print(remaining);
    Serial.println(F(" sec left"));
  }

  if (elapsed >= CALIB_DURATION) {
    compass.setCalibration(calMinX, calMaxX, calMinY, calMaxY, calMinZ, calMaxZ);
    saveCalibration();
    calibrating = false;
    Serial.println(F("=== CALIBRATION DONE ==="));
    Serial.print(F("X:")); Serial.print(calMinX); Serial.print(F(" .. ")); Serial.println(calMaxX);
    Serial.print(F("Y:")); Serial.print(calMinY); Serial.print(F(" .. ")); Serial.println(calMaxY);
    Serial.print(F("Z:")); Serial.print(calMinZ); Serial.print(F(" .. ")); Serial.println(calMaxZ);
  }
}

void saveCalibration() {
  int a = EEPROM_CALIB_BASE;
  writeInt(a, calMinX); a += 2;
  writeInt(a, calMaxX); a += 2;
  writeInt(a, calMinY); a += 2;
  writeInt(a, calMaxY); a += 2;
  writeInt(a, calMinZ); a += 2;
  writeInt(a, calMaxZ);
  EEPROM.write(EEPROM_CALIB_FLAG, EEPROM_CALIB_VALUE);
}

void loadCalibration() {
  if (EEPROM.read(EEPROM_CALIB_FLAG) != EEPROM_CALIB_VALUE) {
    Serial.println(F("No calibration in EEPROM"));
    return;
  }
  int a = EEPROM_CALIB_BASE;
  calMinX = readInt(a); a += 2;
  calMaxX = readInt(a); a += 2;
  calMinY = readInt(a); a += 2;
  calMaxY = readInt(a); a += 2;
  calMinZ = readInt(a); a += 2;
  calMaxZ = readInt(a);
  compass.setCalibration(calMinX, calMaxX, calMinY, calMaxY, calMinZ, calMaxZ);
  Serial.println(F("Calibration loaded from EEPROM"));
}

void writeInt(int a, int v) {
  EEPROM.write(a, highByte(v));
  EEPROM.write(a + 1, lowByte(v));
}

int readInt(int a) {
  return (EEPROM.read(a) << 8) | EEPROM.read(a + 1);
}

// ==================== УТИЛИТЫ ====================
String padNum(int v, byte w) {
  String s = String(v);
  while (s.length() < w) s = " " + s;
  return s;
}
